package hn.uth.pm1ea0199.controller;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.io.File;import java.util.ArrayList;import hn.uth.pm1ea0199.dao.ContactoDAO;import hn.uth.pm1ea0199.model.Contacto;import hn.uth.pm1ea0199.view.Vistas;
public class ListaActivity extends Activity {
 private ContactoDAO dao;private ListView lista;private ArrayList<Contacto> contactos;private Contacto seleccionado;private TextView estado;
 @Override public void onCreate(Bundle s){super.onCreate(s);dao=new ContactoDAO(this);LinearLayout l=Vistas.pagina(this,"Mis contactos");setContentView(l);estado=new TextView(this);l.addView(estado);lista=new ListView(this);lista.setChoiceMode(ListView.CHOICE_MODE_SINGLE);l.addView(lista,new LinearLayout.LayoutParams(-1,0,1));lista.setOnItemClickListener((p,v,pos,id)->{seleccionado=contactos.get(pos);estado.setText("Seleccionado: "+seleccionado.nombre);});
 Vistas.boton(this,l,"Actualizar").setOnClickListener(v->{if(elegido())startActivity(new Intent(this,RegistroActivity.class).putExtra("id",seleccionado.id));});
 Vistas.boton(this,l,"Eliminar").setOnClickListener(v->{if(elegido()){final Contacto c=seleccionado;new AlertDialog.Builder(this).setTitle("Eliminar contacto").setMessage("¿Eliminar a "+c.nombre+"?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{try{if(dao.eliminar(c.id)){new File(c.imagen).delete();cargar();}}catch(Exception e){Vistas.alerta(this,"No se pudo eliminar.");}}).show();}});
 Vistas.boton(this,l,"Compartir").setOnClickListener(v->{if(elegido()){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,"Contacto: "+seleccionado.nombre);i.putExtra(Intent.EXTRA_TEXT,"Nombre: "+seleccionado.nombre+"\nPaís: "+seleccionado.pais+"\nTeléfono: "+seleccionado.telefono+"\nNota: "+seleccionado.nota);try{startActivity(Intent.createChooser(i,"Compartir contacto"));}catch(ActivityNotFoundException e){Vistas.alerta(this,"No hay aplicaciones para compartir.");}}});
 Vistas.boton(this,l,"Ver fotografía").setOnClickListener(v->{if(elegido()){ImageView f=new ImageView(this);f.setAdjustViewBounds(true);f.setMaxHeight(Vistas.dp(this,380));f.setContentDescription("Fotografía de "+seleccionado.nombre);Vistas.mostrar(f,seleccionado.imagen);new AlertDialog.Builder(this).setTitle(seleccionado.nombre).setView(f).setPositiveButton("Cerrar",null).show();}});
 Vistas.boton(this,l,"Llamar").setOnClickListener(v->{if(elegido())startActivity(new Intent(this,LlamarActivity.class).putExtra("id",seleccionado.id));});Vistas.boton(this,l,"Volver al registro").setOnClickListener(v->finish());}
 private boolean elegido(){if(seleccionado!=null)return true;Vistas.alerta(this,"Selecciona un contacto de la lista.");return false;}
 private void cargar(){try{seleccionado=null;contactos=dao.listar();String[] filas=new String[contactos.size()];for(int i=0;i<filas.length;i++)filas[i]=contactos.get(i).toString();lista.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_list_item_single_choice,filas));estado.setText(filas.length==0?"No hay contactos. Registra el primero.":"Selecciona un contacto ("+filas.length+")");}catch(Exception e){Vistas.alerta(this,"No se pudieron consultar los contactos.");}}
 @Override protected void onResume(){super.onResume();cargar();}
 @Override protected void onDestroy(){dao.close();super.onDestroy();}
}
